  const hold = new Uint8Array(W * H);
  const keepBox = (x0, y0, x1, y1, soft) => { for (let y = Math.max(0, y0); y <= Math.min(H - 1, y1); y++) for (let x = Math.max(0, x0); x <= Math.min(W - 1, x1); x++) { keep[y * W + x] = 1; if (!soft) hold[y * W + x] = 1; } };

