  m.entry = [st.cx, st.cy];
  m.g[door[1]][door[0]] = "c"; m.o[door[1]][door[0]] = " ";
  m.portals.push({ x: door[0], y: door[1], to: "town", tx: DIM_TOWN.land[0], ty: DIM_TOWN.land[1], label: "버드나무광장 (귀환)" });
