    for (let i = 0; i < packsIn[j] && budget > 0; i++) {
      const n = Math.min(budget, ri(box, DIM.pack[0], DIM.pack[1]));
      budget -= n;
      spawns.push({ k: kindFor(t), n, at: pick(spots), room: k, el: 0 });
    }
