      if (shape === "cross") return big ? Math.abs(u) < 0.7 || Math.abs(v) < 0.7 : Math.abs(u) < 0.42 || Math.abs(v) < 0.42;
      if (shape === "octagon") return Math.abs(u) + Math.abs(v) <= (big ? 1.62 : 1.5);
      if (shape === "ell") return big ? !(u > 0.34 && v < -0.34) : !(u > 0.15 && v < -0.15);
