      const vert = r.h >= r.w;
      const at = (s, t) => (vert ? [r.cx + t, s] : [s, r.cy + t]);
      const s0 = vert ? r.y0 : r.x0, s1 = vert ? r.y1 : r.x1;
      let head = s0;
