    let all = true;
    for (let dy = 0; dy < 3 && all; dy++) for (let dx = 0; dx < 4 && all; dx++) if (m.o[y + dy][x + dx] !== "h" || used.has((y + dy) * m.w + x + dx)) all = false;
    if (!all) continue;
    for (let dy = 0; dy < 3; dy++) for (let dx = 0; dx < 4; dx++) used.add((y + dy) * m.w + x + dx);
