      const r = [clamp(sp.r[0] | 0, 0, m.w - 1), clamp(sp.r[1] | 0, 0, m.h - 1), clamp(sp.r[2] | 0, 0, m.w - 1), clamp(sp.r[3] | 0, 0, m.h - 1)];
