/** What rank does to a monster: 1 is an elite, 2 a hunting ground's field boss. */
const ELITE = [{ hp: 1, atk: 1, xp: 1 }, { hp: 3.5, atk: 1.4, xp: 4 }, { hp: 14, atk: 1.8, xp: 30 }];
const mobMax = (mob) => Math.round(MOBS[mob.k].hp * ELITE[mob.el].hp);

