    const h = SKILL.hawk, far = h.k * clamp((d - h.d0) / h.span, 0, 1);
    if (far >= h.k * 0.6) rt.ev.push(["a", p.eid, 115, Math.round(mob.x), Math.round(mob.y - 6), p.dir]);
    k *= 1 + far;
