  if (!from.length) return Infinity;
  const path = walk(W, m.h, from, (i) => Math.max(Math.abs((i % W) - tx), Math.abs(Math.floor(i / W) - ty)) <= 1, (j) => (m.reach[j] ? 1 : Infinity), tx, ty);
