    if (st === 4) return bad("이미 마친 퀘스트입니다");
    if (st === -1) return bad("다른 길을 골랐습니다");
    if (ch.lvl < q.req.lv) return bad(`레벨 ${q.req.lv} 이상이어야 합니다`);
    if (q.req.main && ch.q.i < QUESTS.length) return bad("앞선 주요 의뢰를 모두 마쳐야 합니다");
