// Runtime instances never persist. An unfinished rescue wakes at the Oasis boarding post.
function airshipReturn(st) {
  return st.won ? AIRSHIP_DECK : st.from;
}
// ───────────────────────────── 보스전리품 (boss trophies) and the solo story fight ─────────────────────────────
