  if (!st) return;
  const [map, x, y] = st.airship ? airshipReturn(st) : st.from;
  if (p.dead) { p.dead = false; const s = stats(p); p.hp = Math.round(s.mhp * 0.5); p.mp = Math.max(p.mp, Math.round(s.mmp * 0.5)); }
  if (!st.airship) p.storyBack = 1;
