    rewardGear(S, p, Tt, R.gearQ[g - 1]);
    gainXp(S, p, Math.round(tierXp(Tt) * R.xp[g - 1]));
    gainLife(S, p, J.skill, life);
    addRep(S, p, J.npc, R.rep);
    toast(p, `[${J.name}] ${"CBAS"[g - 1]} 등급! 오늘의 보수를 받았습니다.`);
