    const tx = ri(c.box, x0, x1), ty = ri(c.box, y0, y1);
    if (!aptFree(m, c, tx, ty)) continue;
    const e = aptAdd(c, t, tx, ty, t === 2 ? COOP_APT.sofaHp : COOP_APT.pileHp);
    e.due = now + COOP_APT.spreadMs;
